struct UninstalledDocumentEnvelopeRetirement<P, M>
where P: Clone + ToValue + FromValue, M: Clone + ToValue + FromValue + self::Mutation<P>,
{
    active: Option<Box<dyn ErasedSnapshotRetirement>>,
    owners: Option<DocumentStoreOwners<P, M>>,
}

impl<P, M> ErasedSnapshotRetirement for UninstalledDocumentEnvelopeRetirement<P, M>
where P: Clone + ToValue + FromValue + Send + Sync + 'static, M: Clone + ToValue + FromValue + self::Mutation<P> + Send + 'static,
{
    fn close_step(&mut self, grant: RetainedCloneGrant) -> Result<RetainedCloneStep, semio_framework_value::ValueError> {
        if self.active.is_some() { return artifact_retirement_box_close_step(&mut self.active, grant); }
        if let Some(owners) = self.owners.as_mut() {
            let step = owners.close_uninstalled_owners_step(grant)?;
            if matches!(step, RetainedCloneStep::Complete(_)) && owners.uninstalled_owners_terminal_is_empty() { self.owners.take(); }
            return Ok(step);
        }
        Ok(RetainedCloneStep::Complete(RetainedCloneProgress::default()))
    }
    fn next_copy_byte_demand(&self) -> Result<usize, semio_framework_value::ValueError> { Ok(self.demands(0)?.copy_bytes) }
    fn next_capacity_byte_demand(&self, body: usize) -> Result<usize, semio_framework_value::ValueError> { Ok(self.demands(body)?.capacity_bytes) }
    fn next_release_byte_demand(&self) -> Result<usize, semio_framework_value::ValueError> { Ok(self.demands(0)?.release_bytes) }
    fn next_depth_demand(&self) -> Result<usize, semio_framework_value::ValueError> { Ok(self.demands(0)?.depth) }
    fn terminal_is_empty(&self) -> bool { self.active.is_none() && self.owners.is_none() }
}

impl<P, M> UninstalledDocumentEnvelopeRetirement<P, M>
where P: Clone + ToValue + FromValue, M: Clone + ToValue + FromValue + self::Mutation<P>,
{
    fn demands(&self, body: usize) -> Result<semio_framework_value::RetirementDemand, semio_framework_value::ValueError> {
        if let Some(active) = self.active.as_ref() { return artifact_retirement_box_demands(active, body); }
        self.owners.as_ref().map_or(Ok(Default::default()), |owners| owners.uninstalled_owners_demands(body))
    }
}
